//! Regenerates `packages/protocol-ts/src/generated.ts` from the Rust types
//! in the `shopcore-protocol` crate. Run via `just gen-types`.
//!
//! Never edit the generated file by hand; CI fails if it is out of date.

use std::path::PathBuf;
use ts_rs::TS;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let out_path = manifest_dir.join("../../packages/protocol-ts/src/generated.ts");
    let mut contents = String::from("// Generated by `just gen-types` (ts-rs). DO NOT EDIT.\n\n");
    // ts-rs emits `import type { X } from "./X"` for every referenced
    // TS type, assuming one file per type. All types live in THIS one
    // file, so those imports are dangling — strip them here (never by
    // hand-editing the generated file).
    for exported in [
        shopcore_protocol::Pong::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::SkuHitDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::CartLineDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::CartTotalsDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::CartViewDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::SessionDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::StatusDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::HardwareStatusPayload::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::SaleCompletedPayload::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::SampleBarcodeDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::ReceiptLineDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::ReceiptPaymentDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::ReceiptDto::export_to_string(&ts_rs::Config::default())?,
        shopcore_protocol::SaleCompletedDto::export_to_string(&ts_rs::Config::default())?,
    ] {
        for line in exported.lines() {
            if !line.starts_with("import type {") {
                contents.push_str(line);
                contents.push('\n');
            }
        }
        contents.push('\n');
    }
    std::fs::write(&out_path, contents)?;
    println!("wrote {}", out_path.display());
    Ok(())
}
